contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 initialSupply, uint256 mintAmount) public {
        require(mintAmount <= 2**128);
        c = new C(initialSupply, "n", "s");
        c.mintToken(address(this), mintAmount);
        uint256 total = c.totalSupply();
        uint256 bal = c.balanceOf(address(this));
        assert(total == initialSupply + mintAmount && bal == initialSupply + mintAmount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 initialSupply, uint256 burnAmount) public {
        require(initialSupply <= 2**128);
        require(burnAmount <= initialSupply);
        c = new C(initialSupply, "n", "s");
        c.burn(burnAmount);
        uint256 total = c.totalSupply();
        uint256 bal = c.balanceOf(address(this));
        assert(total == initialSupply - burnAmount && bal == initialSupply - burnAmount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 supply, address to, uint256 extra) public {
        require(supply > 0);
        require(to != address(this));
        c = C(address(new C(supply, "n", "s")));
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 tsBefore = c.totalSupply();
        uint256 value = balBefore + extra;
        bool reverted;
        try c.transfer(to, value) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.balanceOf(address(this)) == balBefore && c.balanceOf(to) == toBefore && c.totalSupply() == tsBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public {
        require(v > 0);
        uint256 balBefore = c.balanceOf(address(this));
        bool reverted;
        if (v > balBefore) {
            try c.transfer(address(this), v) returns (bool) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
        } else {
            uint256 supplyBefore = c.totalSupply();
            bool ok = c.transfer(address(0xDead), v);
            assert(ok && c.balanceOf(address(this)) == balBefore - v && c.totalSupply() == supplyBefore);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, uint256 value) public {
        require(!c.frozenAccount(from));
        uint256 fromBefore = c.balanceOf(from);
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        if (from == address(this)) {
            try c.transfer(address(0), value) { reverted = false; }
            catch { reverted = true; }
        } else {
            reverted = true; // zero-address transfers from this contract's sender are checked below
        }
        if (from != address(this)) {
            // sender is always this contract; check directly
            try c.transfer(address(0), value) { reverted = false; }
            catch { reverted = true; }
        }
        assert(reverted && c.balanceOf(address(this)) == fromBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}
